declare function readline(): string;

// Author-only reference solution. Paste into CodinGame with TypeScript selected.
// Exact integer fractions make decimal half-way rounding deterministic.
function runReference(): void {
  const [countText, yearsText, rateText] = readline().split(' ');
  const count = Number(countText);
  const years = Number(yearsText);
  const k = BigInt(count);
  const n = BigInt(years);
  const [rateWhole, rateFraction = ''] = rateText.split('.');
  const rateUnits = BigInt(rateWhole) * 10000n
    + BigInt(rateFraction.padEnd(4, '0'));

  const incomes: bigint[] = [];
  let sumX = 0n;
  let sumY = 0n;
  let sumXX = 0n;
  let sumXY = 0n;

  for (let i = 0; i < count; i++) {
    const [gross, taxes] = readline().split(' ').map(value => BigInt(value));
    const x = BigInt(i + 1);
    const y = gross - taxes;
    incomes.push(y);
    sumX += x;
    sumY += y;
    sumXX += x * x;
    sumXY += x * y;
  }

  // slope = slopeNumerator / slopeDenominator.
  const slopeNumerator = k * sumXY - sumX * sumY;
  const slopeDenominator = k * sumXX - sumX * sumX;
  const denominator = k * slopeDenominator;
  const interceptNumerator = sumY * slopeDenominator - slopeNumerator * sumX;
  const predictions: bigint[] = [];
  for (let i = 1; i <= years; i++) {
    const x = k + BigInt(i);
    predictions.push(k * slopeNumerator * x + interceptNumerator);
  }
  const totalPrediction = predictions.reduce((sum, value) => sum + value, 0n);

  function format(numerator: bigint, divisor: bigint): string {
    const absolute = numerator < 0n ? -numerator : numerator;
    const scaled = absolute * 100n;
    let cents = scaled / divisor;
    if ((scaled % divisor) * 2n >= divisor) {
      cents += 1n;
    }
    const sign = numerator < 0n && cents !== 0n ? '-' : '';
    return `${sign}${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
  }

  console.log(incomes.map(value => format(value, 1n)).join(' '));
  console.log(format(predictions[0], denominator));
  console.log(predictions.map(value => format(value, denominator)).join(' '));
  console.log(format(totalPrediction, denominator * n));
  console.log(format(totalPrediction * 10000n, denominator * n * rateUnits));
}

runReference();
